from pathlib import Path
p=Path('.')
h=(p/'selftest.py').read_text().replace('selftest.input.json','persistent-selftest.input.json')
(p/'persistent_handwritten.py').write_text(h,encoding='utf-8')
s=(p/'optimization_selftest.py').read_text()
s=s.replace('import compiled_policy as compiled','import persistent_policy_v3 as compiled').replace('import selftest as handwritten','import persistent_handwritten as handwritten')
s=s.replace('compiled._partition','compiled.accepted._partition').replace('compiled.EXPECTED_REFERENCE_HASHES','compiled.accepted.EXPECTED_REFERENCE_HASHES')
s=s.replace('optimization-models.json','persistent-v3-models.json').replace('optimization-equivalence.json','persistent-v3-equivalence.json').replace('optimization-summary.json','persistent-v3-summary.json')
s=s.replace("['compiled_policy.py','optimization_selftest.py']", "['persistent_policy_v3.py','persistent_selftest_v3.py','persistent_handwritten.py','compiled_policy.py']")
s=s.replace("        self.results.append(record)", "        self.results.append(record)\n        with (ROOT/'persistent-v3-progress.jsonl').open('a',encoding='utf-8') as stream:\n            stream.write(json.dumps({'completed':len(self.results),'process_cpu_seconds':time.process_time(),'record':record},ensure_ascii=True)+'\\n')")
s=s.replace("            self.models[key]={'instance':deepcopy(instance),'trace':deepcopy(trace)}", "            self.models[key]={'instance':deepcopy(instance),'trace':deepcopy(trace)}\n            with (ROOT/'persistent-v3-model-inputs.jsonl').open('a',encoding='utf-8') as stream:\n                stream.write(json.dumps({'model_key':key,**self.models[key]},ensure_ascii=True)+'\\n')")
s=s.replace("'statistics':c.statistics}", "'statistics':c.statistics,'persistent_diagnostics':c.diagnostics()}")
s=s.replace("if __name__=='__main__': main()", "if __name__=='__main__':\n    import traceback\n    try: main()\n    except BaseException:\n        (ROOT/'persistent-v3-campaign-failure.txt').write_text(traceback.format_exc(),encoding='utf-8')\n        raise")
(p/'persistent_selftest_v3.py').write_text(s,encoding='utf-8')